#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.3 Pro Terminal - Complete All-in-One Installer
# Updates in v7.3:
#   - Split Overview TP/SL controls into 2 dedicated buttons:
#       1) Check TP/SL Now (Fast live check & status update)
#       2) Visual TP/SL Report (Separate chart gallery on demand)
#   - Added working Manual Exit button on every OPEN Tracked Signal:
#       * Closes position at live market price
#       * Records exact P&L (% and R) in Winrate / 24H / 7D reports
#       * Replies to original Telegram signal with final P&L & chart
# + Strategy Studio Pro (Per-Strategy Parameters Menu + Presets +
#   Multi-TF Matrix + 500-Bar Walk-Forward Backtester)
# + Unified Obsidian Gold Pro Palette (Obsidian & Bento HUD)
# + Clean Overview Hierarchy + Dedicated Full-Screen Live Console
# Fresh Install + Safe Repair/Upgrade (Preserves config.json,
# active_trades.json, sent_signals.json, strategy_presets.json
# & custom_strategy.py)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"

echo "========================================================"
echo "  kaviancrypto v7.3 Pro - All-in-One Installer & Upgrade"
echo "  Split Check/Visual TP-SL + Live Manual Exit & TG Report"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_3.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_3.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_3.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v7.3 core files ==="
